"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left".  They compare every number with what their own debugger shows and they
paste the reported file names straight into a ticket, so the report has to be
exact:

* addresses and sizes are reported with the full width of the target's address
  space -- nothing is rounded or truncated to 32 bits;
* reserved ranges are part of the report when ``include_reserved`` is set;
* a file name is only reported when it can be handed back as something the
  caller can open (``C:\\...`` or ``\\\\server\\share\\...``); NT device names
  such as ``\\Device\\HarddiskVolume4\\...`` are translated, and a region that
  has no file behind it -- or whose file cannot be named in an openable form --
  reports ``None`` rather than a placeholder;
* every failure is classified as a :class:`~wvas.errors.WVasError`.
"""

import ctypes
import os

from . import _winapi as w
from .errors import WVasError

# System file names are not limited to MAX_PATH: an NT device name, a UNC
# target or a long path all need the full 32K character budget, and truncating
# them silently produces paths nobody can open.
PATH_BUFFER_CHARS = 32768

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

# Device names that always describe a UNC share rather than a local volume.
_SHARE_DEVICES = (
    "\\device\\mup\\",
    "\\device\\lanmanredirector\\",
    "\\device\\webdavredirector\\",
    "\\device\\davwwwclient\\",
)

_MISSING = object()


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name."""
    return _PROTECTION_NAMES.get(protect & 0xFF, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name."""
    return _TYPE_NAMES.get(region_type, "private")


# ---- process handles -------------------------------------------------------

def _process_exists(pid):
    """True when ``pid`` names a process the system still lists."""
    if w.EnumProcesses is None:
        return False
    wanted = 4096
    for _ in range(4):
        buffer = (ctypes.c_uint32 * wanted)()
        needed = ctypes.wintypes.DWORD(0)
        if not w.EnumProcesses(buffer, ctypes.sizeof(buffer), ctypes.byref(needed)):
            return False
        count = needed.value // ctypes.sizeof(ctypes.c_uint32)
        if count < wanted:
            return pid in [buffer[index] for index in range(count)]
        wanted *= 4
    return False


def _classify_open_failure(pid, error):
    """Turn an ``OpenProcess`` failure into a classified error."""
    if error == w.ERROR_ACCESS_DENIED:
        kind = "access-denied"
    elif error == w.ERROR_INVALID_PARAMETER:
        # Windows reports an unknown pid as "invalid parameter"; a pid that is
        # still listed but cannot be opened is a permission problem.
        kind = "access-denied" if _process_exists(pid) else "no-such-process"
    elif error in (w.ERROR_FILE_NOT_FOUND, w.ERROR_PATH_NOT_FOUND):
        kind = "no-such-process"
    else:
        kind = "query-failed"
    return WVasError(
        "cannot open process for reading (winerror %s)" % error, kind=kind, pid=pid
    )


def _open_process(pid):
    if isinstance(pid, bool) or not isinstance(pid, int) or pid <= 0:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if not w.SUPPORTED:
        raise WVasError(
            "this platform cannot audit a virtual address space",
            kind="unsupported",
            pid=pid,
        )
    handle = w.OpenProcess(
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ, False, pid
    )
    if handle:
        return handle
    error = w.last_error()
    # A process that refuses PROCESS_QUERY_INFORMATION may still answer a
    # limited query, which is enough for the address space walk.
    handle = w.OpenProcess(w.PROCESS_QUERY_LIMITED_INFORMATION, False, pid)
    if handle:
        return handle
    raise _classify_open_failure(pid, error or w.last_error())


def _close(handle):
    if handle and w.CloseHandle is not None:
        w.CloseHandle(handle)


# ---- turning system names into paths the caller can open --------------------

def _string_list(buffer, length):
    """Split a double-null terminated block returned by the Win32 API."""
    if length <= 0:
        return []
    return [part for part in ctypes.wstring_at(buffer, length).split("\0") if part]


def _drive_roots():
    """The drive roots of this machine, e.g. ``['C:\\', 'D:\\']``."""
    if w.GetLogicalDriveStringsW is None:
        return []
    buffer = ctypes.create_unicode_buffer(256)
    length = w.GetLogicalDriveStringsW(len(buffer) - 1, buffer)
    return _string_list(buffer, length)


def _dos_device_names(name):
    """The device names ``name`` is known by, e.g. ``\\Device\\HarddiskVolume4``."""
    if w.QueryDosDeviceW is None or not name:
        return []
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    length = w.QueryDosDeviceW(name, buffer, len(buffer))
    return _string_list(buffer, length)


def _mount_points(volume_name):
    """The roots ``\\?\Volume{...}\`` is mounted at, e.g. ``['C:\\']``."""
    if w.GetVolumePathNamesForVolumeNameW is None:
        return []
    needed = ctypes.wintypes.DWORD(0)
    buffer = ctypes.create_unicode_buffer(256)
    if not w.GetVolumePathNamesForVolumeNameW(
        volume_name, buffer, len(buffer), ctypes.byref(needed)
    ):
        if w.last_error() != w.ERROR_MORE_DATA or not needed.value:
            return []
        buffer = ctypes.create_unicode_buffer(needed.value + 1)
        if not w.GetVolumePathNamesForVolumeNameW(
            volume_name, buffer, len(buffer), ctypes.byref(needed)
        ):
            return []
    return _string_list(buffer, needed.value)


def _preferred_root(roots):
    """Pick the mount point a support engineer would recognise."""
    drives = [root for root in roots if len(root) == 3 and root[1] == ":"]
    pool = sorted(drives or roots)
    if not pool:
        return None
    root = pool[0]
    return root if root.endswith("\\") else root + "\\"


def _volumes():
    """Yield ``(volume_guid_path, mount_points)`` for every local volume."""
    if w.FindFirstVolumeW is None or w.FindNextVolumeW is None:
        return
    buffer = ctypes.create_unicode_buffer(256)
    handle = w.FindFirstVolumeW(buffer, len(buffer))
    if not handle or handle == w.INVALID_HANDLE:
        return
    try:
        while True:
            yield buffer.value, _mount_points(buffer.value)
            if not w.FindNextVolumeW(handle, buffer, len(buffer)):
                break
    finally:
        if w.FindVolumeClose is not None:
            w.FindVolumeClose(handle)


def _build_device_map():
    """Map every NT device name we can resolve onto an openable root."""
    mapping = {}

    def add(device, root):
        if not device or not root:
            return
        mapping.setdefault(device.lower().rstrip("\\"), set()).add(root)

    for drive in _drive_roots():
        for device in _dos_device_names(drive.rstrip("\\")):
            add(device, drive)
    for volume, roots in _volumes():
        root = _preferred_root(roots)
        if root is None:
            continue
        guid = volume[4:].rstrip("\\")          # 'Volume{...}'
        add(guid, root)
        for device in _dos_device_names(guid):
            add(device, root)
    return mapping


def _dos_path_from_device(name, device_map):
    """Translate ``\\Device\\...\\rest`` into ``C:\\rest`` (or a UNC path)."""
    lowered = name.lower()
    for prefix in _SHARE_DEVICES:
        if lowered.startswith(prefix):
            return "\\\\" + name[len(prefix):]
    best = None
    for device in device_map:
        if not (lowered == device or lowered.startswith(device + "\\")):
            continue
        if best is None or len(device) > len(best):
            best = device
    if best is None:
        return None
    root = sorted(device_map[best])[0]
    return root + name[len(best):].lstrip("\\")


def _openable_path(name, device_map):
    """Return ``name`` as a path the caller can open, or ``None``.

    The system hands out file names in whatever form the object manager knows
    them: NT device paths (``\\Device\\HarddiskVolume4\\...``), object manager
    paths (``\\??\\...``), extended length paths (``\\?\\...``) or plain DOS
    paths.  Only the last two are useful in a support ticket, so everything
    else is translated -- and anything that cannot be translated is reported
    as "no file name" instead of leaking a device path.
    """
    if not name:
        return None
    name = name.strip("\0")
    if not name:
        return None

    if name.startswith("\\??\\"):
        return _openable_path(name[4:], device_map)
    if name.startswith("\\\\.\\"):
        return _openable_path(name[4:], device_map)
    if name.startswith("\\\\?\\"):
        remainder = name[4:]
        if remainder.upper().startswith("UNC\\"):
            return "\\\\" + remainder[4:]
        return _openable_path(remainder, device_map)

    if len(name) >= 3 and name[1] == ":" and name[2] == "\\":
        return name
    if name.startswith("\\\\"):
        return name

    if name.startswith("\\"):
        return _dos_path_from_device(name, device_map)

    # A bare 'Volume{...}\file' or 'HarddiskVolume4\file' style name.
    return _dos_path_from_device("\\" + name, device_map)


def _system_name(handle, address, buffer):
    """The raw system name of the file mapped at ``address``, or ``None``."""
    if w.GetMappedFileNameW is None:
        return None
    written = w.GetMappedFileNameW(
        handle, ctypes.c_void_p(address), buffer, len(buffer)
    )
    if not written:
        # Anonymous mappings, private memory and pages we may not read all
        # fail here; none of them has a file name to report.
        return None
    return buffer.value


# ---- walking the address space ---------------------------------------------

def _scan_regions(handle, pid, include_reserved):
    """Walk the target's address space with ``VirtualQueryEx``.

    Every region is returned exactly as the system describes it: full width
    base address, full width size, and the state, protection and type the
    query reported.  Reserved ranges take part when ``include_reserved`` is
    set; free ranges never do.
    """
    wanted = (w.MEM_COMMIT, w.MEM_RESERVE) if include_reserved else (w.MEM_COMMIT,)
    info = w.MEMORY_BASIC_INFORMATION()
    size_of_info = ctypes.sizeof(info)
    address = 0
    scanned = []
    first = True
    # The walk ends when VirtualQueryEx refuses the address, which is what it
    # does once the top of the target's user address space is passed.  The
    # iteration cap only guards against a system that never says no.
    for _ in range(1 << 22):
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(info), size_of_info
        )
        if not written:
            if first:
                error = w.last_error()
                kind = "access-denied" if error == w.ERROR_ACCESS_DENIED else (
                    "query-failed"
                )
                raise WVasError(
                    "VirtualQueryEx failed (winerror %s)" % error, kind=kind, pid=pid
                )
            break
        first = False
        base = info.BaseAddress or 0
        region_size = info.RegionSize or 0
        if region_size and info.State in wanted:
            scanned.append((
                base,
                region_size,
                info.State,
                info.Protect,
                info.Type,
                info.AllocationBase or 0,
            ))
        following = base + region_size
        if following <= address:
            break
        address = following
    return scanned


def _image_allocations(handle, scanned, device_map):
    """Summarise the image regions of a scan as ``{base: (end, path)}``."""
    images = {}
    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    for base, size, state, _protect, region_type, allocation_base in scanned:
        if region_type != w.MEM_IMAGE or state != w.MEM_COMMIT:
            continue
        key = allocation_base or base
        entry = images.get(key)
        if entry is None:
            name = _system_name(handle, key, buffer)
            images[key] = (base + size, _openable_path(name, device_map))
        else:
            images[key] = (max(entry[0], base + size), entry[1])
    return images


def _enumerate_modules(handle, device_map):
    """List the images the target has loaded, ``[(base, size, path), ...]``."""
    if w.EnumProcessModulesEx is None:
        return []
    modules = []
    capacity = 256
    pointer_size = ctypes.sizeof(ctypes.c_void_p)
    for _ in range(8):
        array = (ctypes.c_void_p * capacity)()
        needed = ctypes.wintypes.DWORD(0)
        ok = w.EnumProcessModulesEx(
            handle, array, ctypes.sizeof(array), ctypes.byref(needed),
            w.LIST_MODULES_ALL,
        )
        error = w.last_error()
        count = needed.value // pointer_size if needed.value else 0
        if ok and count <= capacity:
            modules = [array[index] for index in range(count)]
            break
        if not ok and error not in (
            w.ERROR_BAD_LENGTH, w.ERROR_INSUFFICIENT_BUFFER, w.ERROR_PARTIAL_COPY
        ):
            break
        if count <= capacity:
            break
        capacity = count + 16

    buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
    listed = []
    for base in modules:
        if not base:
            continue
        listed.append((base, _module_size(handle, base),
                       _module_path(handle, base, buffer, device_map)))
    return listed


def _module_size(handle, base):
    """The size of the image loaded at ``base``, or 0 when unknown."""
    if w.GetModuleInformation is None:
        return 0
    info = w.MODULEINFO()
    if not w.GetModuleInformation(
        handle, ctypes.c_void_p(base), ctypes.byref(info), ctypes.sizeof(info)
    ):
        return 0
    return int(info.SizeOfImage or 0)


def _module_path(handle, base, buffer, device_map):
    """The disk path of the image at ``base``, or ``None`` when unavailable."""
    if w.GetModuleFileNameExW is None:
        return None
    written = w.GetModuleFileNameExW(
        handle, ctypes.c_void_p(base), buffer, len(buffer)
    )
    if not written:
        return None
    return _openable_path(buffer.value, device_map)


# ---- public API ------------------------------------------------------------

def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    The regions are ordered by ``base``.  With ``include_reserved`` both
    committed and reserved ranges are reported, otherwise only the committed
    ones.
    """
    handle = _open_process(pid)
    try:
        device_map = _build_device_map()
        image_paths = {
            base: path for base, _size, path in _enumerate_modules(handle, device_map)
        }
        scanned = _scan_regions(handle, pid, include_reserved)
        buffer = ctypes.create_unicode_buffer(PATH_BUFFER_CHARS)
        named = {}
        result = []
        for base, size, state, protect, region_type, allocation_base in scanned:
            result.append({
                "base": base,
                "size": size,
                "state": "reserve" if state == w.MEM_RESERVE else "commit",
                "type": type_name(region_type),
                "protect": protection_name(protect),
                "path": _region_path(
                    handle, state, region_type, base, allocation_base,
                    image_paths, named, buffer, device_map,
                ),
                "image": region_type == w.MEM_IMAGE,
            })
        result.sort(key=lambda item: item["base"])
        return result
    finally:
        _close(handle)


def _region_path(handle, state, region_type, base, allocation_base,
                 image_paths, named, buffer, device_map):
    """The file behind a region, as an openable path, or ``None``."""
    if state != w.MEM_COMMIT:
        # Reserved ranges have no contents, so nothing can back them.
        return None
    if region_type == w.MEM_PRIVATE:
        return None
    if region_type == w.MEM_IMAGE:
        path = image_paths.get(allocation_base or base, _MISSING)
        if path is not _MISSING:
            return path
    key = allocation_base or base
    if key in named:
        return named[key]
    path = _openable_path(_system_name(handle, key, buffer), device_map)
    named[key] = path
    return path


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Each image is reported once.  An image whose file cannot be named in a
    form the caller can open is still reported, with ``path`` set to ``None``.
    """
    handle = _open_process(pid)
    try:
        device_map = _build_device_map()
        scanned = _scan_regions(handle, pid, False)
        images = _image_allocations(handle, scanned, device_map)
        listed = {}
        for base, size, path in _enumerate_modules(handle, device_map):
            if base in listed:
                continue
            if not size and base in images:
                size = images[base][0] - base
            listed[base] = {"path": path, "base": base, "size": size}
        for base in sorted(images):
            if base in listed:
                continue
            end, path = images[base]
            listed[base] = {"path": path, "base": base, "size": max(end - base, 0)}

        unique = []
        seen = set()
        for item in sorted(listed.values(), key=lambda entry: entry["base"]):
            if item["path"] is not None:
                key = os.path.normcase(item["path"])
                if key in seen:
                    continue
                seen.add(key)
            unique.append(item)
        return unique
    finally:
        _close(handle)
